-- MASAR's four FICTIONAL DEMO travel packages + read-only access for signed-in sessions.
-- Scope: (1) replaces the catalog SELECT policy so published demo rows whose code starts
-- with 'masar-demo-' are readable by authenticated, active sessions (other demo rows still
-- require the catalog_demo claim; non-demo rules unchanged; no write grants added);
-- (2) inserts the four packages only if neither their id nor code exists (idempotent, no
-- UPDATE/DELETE). Rollback: restore the previous policy text and
--   delete from public.sadeeman_company_packages where code like 'masar-demo-%' and is_demo;
drop policy if exists readable_company_catalog on public.sadeeman_company_packages;
create policy readable_company_catalog on public.sadeeman_company_packages for select to authenticated
 using ((select auth.uid()) is not null and (select public.sadeeman_session_active()) and published and
 (not is_demo or code like 'masar-demo-%' or coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb#>>'{app_metadata,catalog_demo}','false')='true'));
insert into public.sadeeman_company_packages (id, document)
select v.id, v.document from (values
